public class CachedProductRepository : IProductRepository {
    private readonly IProductRepository _inner; private readonly IMemoryCache _cache;
    public CachedProductRepository(IProductRepository inner, IMemoryCache cache)
        { _inner = inner; _cache = cache; }
    public async Task<Product?> GetAsync(int id) =>
        await _cache.GetOrCreateAsync($"product:{id}", e => {
            e.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
            return _inner.GetAsync(id); });
    public async Task UpdateAsync(Product p) {
        await _inner.UpdateAsync(p); _cache.Remove($"product:{p.Id}"); }
}
```
Writes go to the inner repository first and then invalidate the key.

