public class NotificationService(IEnumerable<INotificationChannel> channels,
                                 IPreferenceStore prefs) {
    private readonly Dictionary<ChannelType, INotificationChannel> _byType =
        channels.ToDictionary(c => c.Type);
    public async Task NotifyAsync(Notification n) {
        var enabled = await prefs.GetEnabledChannelsAsync(n.UserId);
        foreach (var type in enabled)
            if (_byType.TryGetValue(type, out var ch))
                await ch.SendAsync(n);
    }
}
